CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(120) NOT NULL,email VARCHAR(255) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'customer',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS categories(id SERIAL PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL,slug VARCHAR(120) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS products(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),seller_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,category_id INT REFERENCES categories(id) ON DELETE SET NULL,name VARCHAR(200) NOT NULL,description TEXT DEFAULT '',price NUMERIC(12,2) NOT NULL CHECK(price>=0),stock INT NOT NULL DEFAULT 0 CHECK(stock>=0),image_url TEXT,is_active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS addresses(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,full_name VARCHAR(120) NOT NULL,phone VARCHAR(30) NOT NULL,county VARCHAR(100) NOT NULL,town VARCHAR(100) NOT NULL,address_line TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id),address_id UUID REFERENCES addresses(id),status VARCHAR(30) NOT NULL DEFAULT 'pending',total NUMERIC(12,2) NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id UUID NOT NULL REFERENCES products(id),seller_id UUID NOT NULL REFERENCES users(id),quantity INT NOT NULL CHECK(quantity>0),unit_price NUMERIC(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE,method VARCHAR(30) NOT NULL,status VARCHAR(30) DEFAULT 'pending',transaction_reference VARCHAR(120),amount NUMERIC(12,2) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_status_history(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE,status VARCHAR(30) NOT NULL,changed_by UUID REFERENCES users(id),note TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,rating INT CHECK(rating between 1 and 5),comment TEXT DEFAULT '',is_approved BOOLEAN DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(product_id,user_id));
INSERT INTO categories(name,slug) VALUES('Electronics','electronics'),('Fashion','fashion'),('Home','home'),('Beauty','beauty'),('Groceries','groceries'),('Phones','phones') ON CONFLICT(slug) DO NOTHING;
